SET NAMES utf8mb4;
-- Guide: nuova pagina Directory e Profilo con città e provincia obbligatorie.
-- Si può rieseguire (ON DUPLICATE KEY UPDATE). Richiede la 2026_11_29.
INSERT INTO page_help (page_key, title, body, more, sort_order) VALUES
('dashboard_directory', 'Directory', 'Cerca le band con profilo visibile per provincia e città: l''elenco, l''indice per provincia e la mappa si aggiornano con i filtri. Un tocco sul segnaposto mostra le band di quel comune.', 'La posizione sulla mappa è il centro del comune, calcolato da città e provincia indicate nel Profilo (mai dall''indirizzo). I profili privati non compaiono. Se una band non è sulla mappa, la sua posizione si calcola al prossimo salvataggio del profilo.', 1180),
('dashboard_profile', 'Profilo', 'Qui modifichi come ti presenti: nome, descrizione, foto profilo, colore e informazioni di contatto. Sono i dati che vedono i visitatori della tua pagina pubblica.', '**Città e provincia sono obbligatorie**, anche dopo la registrazione: senza non si entra nella dashboard; la provincia si sceglie dall''elenco e serve alla Directory per trovarti per zona. Il colore scelto qui resta il tuo accento personale anche cambiando tema grafico. Con «Profilo privato» il profilo sparisce da ricerche, liste e motori di ricerca e la pagina pubblica si apre solo a te, a chi lo gestisce e ai tuoi follower collegati; le tue automazioni e i server MCP continuano a funzionare. In fondo alla pagina trovi l''eliminazione dell''account.', 1020)
ON DUPLICATE KEY UPDATE title = VALUES(title), body = VALUES(body), more = VALUES(more);
